import numpy as np

def find_solutions():
    solutions = []
    # Sample points on the sphere x^2 + y^2 + z^2 = 3
    # Using spherical coordinates
    for theta in np.linspace(0, np.pi, 100):
        for phi in np.linspace(0, 2*np.pi, 100):
            x = np.sqrt(3) * np.sin(theta) * np.cos(phi)
            y = np.sqrt(3) * np.sin(theta) * np.sin(phi)
            z = np.sqrt(3) * np.cos(theta)

            val2 = x*y**3 + y*z**3 + z*x**3
            if np.isclose(val2, 3, atol=0.1):
                solutions.append((x, y, z))
    return solutions

# A more precise search
def find_solutions_precise():
    solutions = []
    # Use a grid of values for x and y, then solve for z
    # x^2 + y^2 + z^2 = 3  =>  z^2 = 3 - x^2 - y^2
    # Let's iterate over a grid
    for x in np.linspace(-np.sqrt(3), np.sqrt(3), 200):
        for y in np.linspace(-np.sqrt(3), np.sqrt(3), 200):
            z2 = 3 - x**2 - y**2
            if z2 >= 0:
                z = np.sqrt(z2)
                if np.isclose(x*y**3 + y*z**3 + z*x**3, 3, atol=0.1):
                    solutions.append((x, y, z))
                if z != 0:
                    z = -np.sqrt(z2)
                    if np.isclose(x*y**3 + y*z**3 + z*x**3, 3, atol=0.1):
                        solutions.append((x, y, z))
    return solutions

