import numpy as np
from scipy.optimize import minimize

def objective(params):
    theta, phi = params
    x = np.sqrt(3) * np.sin(theta) * np.cos(phi)
    y = np.sqrt(3) * np.sin(theta) * np.sin(phi)
    z = np.sqrt(3) * np.cos(theta)
    return -(x*y**3 + y*z**3 + z*x**3)

max_vals = []
for theta_start in np.linspace(0, np.pi, 20):
    for phi_start in np.linspace(0, 2*np.pi, 20):
        res = minimize(objective, [theta_start, phi_start], method='L-BFGS-B')
        if res.success:
            max_vals.append(-res.fun)

print(np.unique(np.round(max_vals, 4)))
